void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
template<class F>void rejects(F f){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}check(rejected,"unsupported/stale European match request accepted");}
GameState reference(){GameState g;g.club_ids.resize(445);g.team_flags.resize(445);g.team_morale.resize(445);g.manager_records.resize(4*0xb0c);g.tactics.resize(4*0x840);g.manager_options.resize(20);g.manager_ratings.resize(240);g.formations.resize(0x580);const uint8_t depth[]={0,5,5,5,5,10,10,10,10,17,17},lane[]={4,1,3,5,7,1,3,5,7,3,5};for(size_t m=0;m<4;++m){g.manager_options[m*5]=1;for(size_t mode=0;mode<2;++mode)for(size_t f=0;f<4;++f)for(size_t row=0;row<11;++row){const auto at=m*0x160+mode*0xb0+f*22+row;g.formations[at]=depth[row];g.formations[at+11]=lane[row];}}return g;}
CareerSnapshot fixture(const GameState& base,bool human){CareerSnapshot state;auto& w=state.world;w=bmh::test::world12::complete_world();w.catalogue.scope.international=false;w.players_initialized=true;w.markets=CareerMarkets{};w.free_players=CareerPlayerPools{};w.settings=CareerSettings{3,6,5,1,false};uint32_t player=1000000,club=2000000;for(auto& [id,c]:w.clubs)for(size_t row=0;row<20;++row){if(c.roster[row].empty()){PlayerRecord p;p.id={player++};p.attributes.name="Reserve";w.players[p.id]=p;c.roster[row]={p.id,uint16_t(row<17?2:0)};}auto& p=w.players.at(c.roster[row].player).attributes;p.w35c=60u|(75u<<7)|(85u<<14);p.w368=uint32_t(c.country)<<27;p.w364=uint32_t(row==0||row==11?0:row<5?1:row<9?2:3);}
    InitialCompetitionFields fields;const size_t counts[]={64,24,32};auto league=w.clubs.begin();for(size_t k=0;k<3;++k){for(size_t row=0;row<counts[k];++row){if(row<4)fields.fields[k].push_back((league++)->first);else{ClubRecord c;c.id={club++};c.name="Abstract club "+std::to_string(c.id.value);c.country=Country(5+(row%27));c.rating=uint8_t((row%8)*32+7);c.morale=25;c.crest={c.id.value};w.crests[c.crest]={"W/TEST.VGA",0};w.clubs[c.id]=c;fields.fields[k].push_back(c.id);}}fields.holders[k]=fields.fields[k][0];}
    if(human){const auto id=fields.fields[0][0];const auto l=w.clubs.at(id).league;w.managers={{3,"Manager",id,l,3}};WatcomRandom random(91);initialize_manager_contracts(w,3,base,{3,false,false,false,6},random);w.managers[0].career.emplace();w.managers[0].career->season_records.emplace();w.managers[0].career->cup_titles.emplace();}
    w.initial_competitions=fields;w.european_campaigns=initial_european_campaigns(w,bmh::test::world12::country_rules(false));state.results=SeasonResults::empty(w.catalogue);state.game_seed=31;state.watcom_seed=91;
    SeasonCalendar calendar;for(const auto& l:w.catalogue.leagues)for(uint8_t r=1;r<=l.rounds();++r)calendar.leagues.push_back({uint16_t(30+r*7),l.id,r});for(uint16_t day=0;day<13;++day)calendar.others.push_back({day,CalendarDomain::shared,uint16_t((day<12?0x40:0)|0x80|(day<9?0x100:0))});calendar.validate(w.catalogue);state.calendar=CalendarCursor{calendar,0,0};state.validate();return state;}
AiLeagueConditions condition(uint32_t date){AiLeagueConditions c;c.date=date;c.month=7;c.temperature=20;c.rain=0;c.spectators=20000;c.referee_properties={24};c.presentation_buttons.assign(0xb4,1);return c;}
std::vector<application::EuropeanDayConditions> inputs(const CareerSnapshot& state){std::vector<application::EuropeanDayConditions> result;const auto ticket=*prepare_day(state);for(const auto& group:ticket.european)result.push_back({group,std::vector<AiLeagueConditions>(group.matches.size(),condition(state.date))});return result;}
void full_programme(){const auto base=reference();const auto source=bmh::test::world12::country_rules(false);for(bool human:{false,true}){auto state=fixture(base,human);const auto initial=state;application::ManagerActionOwner owner{713,0};HumanRoundHooks hooks;hooks.decline_unpresented_events=true;size_t count=0,abstract=0;for(int day=0;day<13;++day){const auto ticket=*prepare_day(state);const auto requests=inputs(state);const auto before=state;const auto old_owner=owner;
            size_t shared_ticks=0;hooks.after_minute=[&](auto& projection,auto& engine,int){++shared_ticks;check(engine.groups.size()==ticket.european.size(),"European groups lost their one shared minute clock");for(size_t g=0;g<engine.groups.size();++g){const auto& actual=engine.groups[g];const auto& expected=ticket.european[g];check(actual.desc[0]==uint8_t(expected.competition)+1&&actual.matches()==int(expected.matches.size()),"shared clock changed original group descriptors");for(size_t m=0;m<expected.matches.size();++m)check(projection.global_club(uint32_t(actual.fixtures[m*2]))==expected.matches[m].home&&projection.global_club(uint32_t(actual.fixtures[m*2+1]))==expected.matches[m].away,"shared clock lost global fixture identities");}};
            if(!day){auto broken=requests;broken.back().matches.pop_back();rejects([&]{application::play_competition_day(state,owner,owner,ticket,base,{source,source},{},{},broken,{3,6,false,true},hooks);});check(state==before&&owner.scope==old_owner.scope&&owner.revision==old_owner.revision,"incomplete last programme leaked earlier match state/RNG");
                HumanRoundHooks interrupted=hooks;interrupted.after_minute=[&](auto&,auto&,int){++owner.revision;throw std::runtime_error("cancelled presenter");};rejects([&]{application::play_competition_day(state,owner,old_owner,ticket,base,{source,source},{},{},requests,{3,6,false,true},interrupted);});check(state==before&&owner.revision==old_owner.revision+1,"cancelled presenter changed career or rewound external owner");owner=old_owner;}
            const auto outcome=application::play_competition_day(state,owner,owner,ticket,base,{source,source},{},{},requests,{3,6,false,true},hooks);
            check(shared_ticks>=90,"actual European shared minute clock did not run");
            for(size_t g=0;g<outcome.european.size();++g){const auto& receipt=outcome.european[g];check(receipt.scores.size()==ticket.european[g].matches.size()&&std::all_of(receipt.end_minutes.begin(),receipt.end_minutes.end(),[](auto minute){return minute>=90&&minute<=124;}),"European Core match did not reach full time");count+=receipt.scores.size();for(const auto& f:ticket.european[g].matches)for(auto id:{f.home,f.away})if(!state.world.clubs.at(id).league.valid())++abstract;}
            check(state.calendar->next_day==day+1&&state.date==uint32_t(day+1)&&owner.revision==old_owner.revision+1,"European day did not publish one date/revision");const auto saved=state;state=read_save(make_save(state));check(state==saved,"real European match state lost on save/reload");
            if(!day){auto repeated=before;auto repeat_owner=old_owner;const auto again=application::play_competition_day(repeated,repeat_owner,repeat_owner,ticket,base,{source,source},{},{},requests,{3,6,false,true},hooks);check(repeated==state&&again.game_draws==outcome.game_draws&&again.watcom_draws==outcome.watcom_draws,"real European matches changed on identical replay");}}
        check(count==264&&abstract>0,"actual Core campaign programme omitted Source matches/abstract clubs");for(const auto& c:*state.world.european_campaigns)check(c.complete&&c.winner.valid(),"real Core programme did not crown all three winners");for(const auto& [id,club]:initial.world.clubs)if(!club.league.valid())check(state.world.clubs.at(id).roster==club.roster,"rating-only club acquired an invented roster");std::cout<<"Real Core European programme human="<<human<<": "<<count<<" matches, "<<abstract<<" abstract team appearances, all boundaries saved\n";}}
void weather_persistence(){const auto base=reference();const auto source=bmh::test::world12::country_rules(false);auto state=fixture(base,true);for(auto& appointment:state.calendar->schedule.others)++appointment.day;state.calendar->next_day=1;state.date=1;state.desktop.emplace();ManagerDesktop desk;desk.seat=3;state.desktop->managers={desk};state.desktop->manager_order={3};state.desktop->matchday_number=77;const auto epoch=calendar_epoch();state.progress=CareerProgress{ProgressPhase::scheduled_event,DayEntry::plain_day,0,0,uint16_t(epoch.year),uint8_t(epoch.weekday),3};state.validate();const auto before=state;application::ManagerActionOwner owner{77,1};
    const auto weather=application::prepare_event_weather(state,owner,owner,std::vector<uint8_t>(50,0x24),{source,source});check(weather.matches.size()==56&&state.prepared_event&&state.prepared_event->groups.size()==3&&owner.revision==2&&state.date==before.date&&state.calendar==before.calendar,"European weather lost its distinct Source groups/date owner");
    auto file=make_save(state);check(file.stream[7]=='H'&&read_save(file)==state,"unstarted European weather did not roundtrip in SH");auto bad=state;bad.prepared_event->groups.back().european=EuropeanCompetition::uefa_cup;rejects([&]{make_save(bad);});auto truncated=file;truncated.stream.pop_back();rejects([&]{read_save(truncated);});
    {
        auto coupon=state;coupon.prepared_event->desk_phase=PreparedEvent::DeskPhase::desks;InitialDeskEvent event;event.matchday_number=77;event.manager_order={3};coupon.desktop->initial_event=event;
        WatcomRandom random(coupon.watcom_seed);prepare_scheduled_pools(coupon,base,random);
        check(coupon.world==state.world&&coupon.prepared_event->pools_matches&&coupon.prepared_event->pools_matches->size()==11&&random.calls()>0,"European coupon did not select eleven actual Source fixtures without changing World");
        check(std::any_of(coupon.prepared_event->pools_matches->begin(),coupon.prepared_event->pools_matches->end(),[&](const auto& f){return !coupon.world.clubs.at(f.home).league.valid()||!coupon.world.clubs.at(f.away).league.valid();}),"European coupon omitted every rating-only club");
        check(read_save(make_save(coupon))==coupon,"European rating-only coupon lost its global references on save");
        auto receipt=*coupon.prepared_event;receipt.desk_phase=PreparedEvent::DeskPhase::complete;coupon.prepared_event.reset();coupon.desktop->initial_event.reset();coupon.world.economy.emplace();auto& ledger=coupon.world.economy->pools.emplace();ledger.appointment=std::make_pair(coupon.season,coupon.date);ledger.managers[3].stake=10000;coupon.world.managers[0].finance->balance=1000000;
        const auto before=coupon;std::vector<PoolsMatchOutcome> outcomes;for(const auto& f:*receipt.pools_matches)outcomes.push_back({f,0});TextDb texts;settle_scheduled_pools(coupon,receipt,outcomes,base,texts);
        check(coupon.world.managers[0].finance->balance==1490000&&coupon.world.economy->pools->managers[3].stake==0&&coupon.world.economy->pools->managers[3].correct==11&&coupon.world.economy->pools->managers[3].winnings==500000&&!coupon.world.economy->pools->appointment&&coupon.game_seed==before.game_seed&&coupon.watcom_seed==before.watcom_seed,"European coupon settlement lost the real sparse manager, Source quota or RNG owner");
        check(coupon.world.players==before.world.players&&read_save(make_save(coupon))==coupon,"European coupon settlement invented player state or lost its save");
        for(const auto& [id,club]:before.world.clubs)check(coupon.world.clubs.at(id).roster==club.roster,"European coupon settlement invented a rating-only roster");
    }
    {
        const auto abstract=std::find_if(state.world.clubs.begin(),state.world.clubs.end(),[](const auto& row){return !row.second.league.valid();})->first;
        auto projection=AiMatchProjection::create_for_european(state,{state.world.managers[0].club,abstract},base,{3,6,false,true});const auto team=int(projection.local_club(abstract));auto native=projection.state;native.projected_match_clubs.clear();
        check(team>=runtime_dimensions.league_teams&&table_position(projection.state,team)==table_position(native,team)&&table_position(native,team)==2,"rating-only attendance position differs from the real Source outside-league path");
        auto gates=state;gates.world.economy.emplace();gates.world.managers[0].career->season_services.emplace();const auto player_count=gates.world.players.size();TextDb texts;texts.strings.assign(TEXT_COUNT,"Authored attendance notice");auto gate_owner=owner;
        const auto attendance=application::book_event_attendance(gates,gate_owner,gate_owner,base,texts,{source,source});
        check(attendance.spectators.size()==56&&gates.prepared_event->gates_booked&&read_save(make_save(gates))==gates,"actual European gates did not retain the Source position operand or saved receipt");
        check(gates.world.players.size()==player_count,"rating-only attendance manufactured players");for(const auto& [id,club]:state.world.clubs)if(!club.league.valid())check(gates.world.clubs.at(id).roster==club.roster,"rating-only attendance manufactured a roster");
    }
    state.prepared_event->desk_phase=PreparedEvent::DeskPhase::complete;state.prepared_event->pools_matches.emplace();file=make_save(state);check(read_save(file)==state,"European known-empty pools/complete desk phase lost on save");state.prepared_event->gates_booked=true;for(auto& group:state.prepared_event->groups)for(auto& match:group.matches)match.spectators=20000;file=make_save(state);check(read_save(file)==state,"European booked gates were lost in SH");
}

